INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48111, 'Job 30:20', 'Job', 30, 20, 'زۀ تا ته فرياد کوم او تۀ زما فرياد نۀ اورې، زۀ ستا په وړاندې ودرېږم خو تۀ ما ته ګورې قدرې هم نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_20.mp3', '', 1761754199, 1761754199),
(48112, 'Job 30:21', 'Job', 30, 21, 'تا ما سره زياتے شروع کړے دے، او د خپل طاقت سره ما له تکليف راکوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_21.mp3', '', 1761754199, 1761754199),
(48113, 'Job 30:22', 'Job', 30, 22, 'تا زۀ په هوا باندې اوچت کړے يم، او په طوفان کښې دې تباه کړے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_22.mp3', '', 1761754199, 1761754199),
(48114, 'Job 30:23', 'Job', 30, 23, 'ما ته پته ده چې تۀ به ما مرګ له بوځې، هغه کور ته کوم چې د ټولو ژوندو دپاره تيار شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_23.mp3', '', 1761754199, 1761754199),
(48115, 'Job 30:24', 'Job', 30, 24, 'څوک د ضرورتمندو خِلاف کار نۀ کوى، کله چې په يو مصيبت کښې هغوئ د مدد دپاره چغې وهى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_24.mp3', '', 1761754199, 1761754199),
(48116, 'Job 30:25', 'Job', 30, 25, 'څوک چې په تکليف کښې وُو ولې ما د هغوئ دپاره ژړا ونۀ کړه څۀ؟ او زما زړۀ په غريبانانو باندې خفه نۀ وو څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_25.mp3', '', 1761754199, 1761754199),
(48117, 'Job 30:26', 'Job', 30, 26, 'خو کله چې ما د ښۀ‌والى لټون وکړو، نو بدوالے راغلو، او کله چې ما د رڼا اِنتظار وکړو، نو تيارۀ راغله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_26.mp3', '', 1761754199, 1761754199),
(48118, 'Job 30:27', 'Job', 30, 27, 'زما زړۀ بې‌قراره او په تکليف دے، او سخت وخت په ما باندې راغلے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_27.mp3', '', 1761754199, 1761754199),
(48119, 'Job 30:28', 'Job', 30, 28, 'زۀ په داسې تيارۀ کښې ګرځم چې رڼا نۀ وى، زۀ د خلقو په مخکښې ودرېږم او د مدد دپاره چغې وهم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_28.mp3', '', 1761754199, 1761754199),
(48120, 'Job 30:29', 'Job', 30, 29, 'زۀ د ګيدړانو ورور يم، او د ګونګا ملګرے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_29.mp3', '', 1761754199, 1761754199),
(48121, 'Job 30:30', 'Job', 30, 30, 'زما څرمن توره شى او وغورزيږى، او زما بدن د تبې په وجه سور وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_30.mp3', '', 1761754199, 1761754199),
(48122, 'Job 30:31', 'Job', 30, 31, 'زما د رباب ساز په ژړا بدل شوے دے، او زما د شپېلۍ آواز د ژړا نه ډک دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_31.mp3', '', 1761754199, 1761754199),
(48123, 'Isaiah 62:1', 'Isaiah', 62, 1, 'چوپ به نه کښېنم زه د صهیون په خاطر پاتې به نه شم غلی د اورشلیم په خاطر ترڅو ونه ځلیږي عدالت د هغه د سهار د رڼا په شان او ونه ځلیږي ژغورنه یې د څراغ په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_1.mp3', '', 1761754199, 1761754199),
(48124, 'Isaiah 62:2', 'Isaiah', 62, 2, 'ای اورشلیمه! وبه ویني عدالت ستا د نړۍ قومونه وبه ګوري ستا شان او شوکت ټول پاچاهان تاته به درکړل شي یو نوی نوم څښتن به کېږدي په تا هغه نوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_2.mp3', '', 1761754199, 1761754199),
(48125, 'Isaiah 62:3', 'Isaiah', 62, 3, 'د ښکلي تاج په شان به شې ته د څښتن په لاس کې شاهي لونګۍ په شان به شې ته د خپل خدای په لاس کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_3.mp3', '', 1761754199, 1761754199),
(48126, 'Isaiah 62:4', 'Isaiah', 62, 4, 'نور به څوک نه یادوي تا د «پرېښودل شوي ښار» په نامه بیا به دې ځمکه «شاړه» نه یادوي خو ستا نوی نوم به وي «د څښتن د خوشحالۍ ښار» او د ځمکې نوم به دې وي «د څښتن ناوې» ځکه چې ستا نه دی څښتن خوشحاله او هغه به وي لکه مېړه د ستا د ځمکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_4.mp3', '', 1761754199, 1761754199),
(48127, 'Isaiah 62:5', 'Isaiah', 62, 5, 'لکه څنګه چې یو ځوان کوي واده له یوې پېغلې سره نو داسې اوسیږي به ستا خلک په تا کې لکه څنګه چې خوشحاله وي یو زوم له خپلې ناوې سره نو داسې خوشحاله به وي خدای له تا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_5.mp3', '', 1761754199, 1761754199),
(48128, 'Isaiah 62:6', 'Isaiah', 62, 6, 'ای اورشلیمه، ستا دېوالونو باندې ما ودرولي دي پهره داران هغوی به هېڅکله شپه او ورځ نه کښېني غلي چې یادوئ څښتن ته د هغه وعدې چپ مه کښېنئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_6.mp3', '', 1761754199, 1761754199),
(48129, 'Isaiah 62:7', 'Isaiah', 62, 7, 'ترڅو جوړ نه کړي اورشلیم یوځل بیا او ترې جوړ نه کړي داسې ښار چې د ستاینې سبب وګرځي ټولې نړۍ دپاره تر هغه وخته څښتن مه پرېږدئ چې کښېني ارام', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_7.mp3', '', 1761754199, 1761754199),
(48130, 'Isaiah 62:8', 'Isaiah', 62, 8, 'په خپل ښي لاس او قوي مټ څښتن قسم کړی دی: «نور به ورنه کړمه غلې دانې دښمنانو ته ستا چې ویې خوري نور به ستا شراب چې دی حاصل ستا د زیار پردي خلک ونه څښي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_8.mp3', '', 1761754199, 1761754199),
(48131, 'Isaiah 62:9', 'Isaiah', 62, 9, 'څوک چې رېبي دا غلې هغوی به وکړي د څښتن ستاینه د ډوډۍ خوړلو وخت کې چې جوړوي څوک د انګورو شراب هغوی به یې وڅښي د څښتن د کور انګړ کې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_9.mp3', '', 1761754199, 1761754199),
(48132, 'Isaiah 62:10', 'Isaiah', 62, 10, 'ای د اورشلیم خلکو، بیرون ووځئ د ښار له دروازو نه لاړ شئ دباندې او چې راستنیږي کوم خلک ستاسو بېرته هغوی ته بیا جوړه کړئ لاره جوړه کړئ لویه لاره او لېرې کړئ تیږې له دې لارې څخه یو بیرغ پورته کړئ ټولو قومونو ته چې ویې ویني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_10.mp3', '', 1761754199, 1761754199),
(48133, 'Isaiah 62:11', 'Isaiah', 62, 11, 'ګورئ، څښتن اعلان کړی دی ټولې نړۍ ته: «ووایئ د اورشلیم خلکو ته چې څښتن دی راروان ستاسو خلاصون دپاره ګورئ، راولي هغه له ځانه سره ژغورل شوي خلک راروان دي هغوی هغه نه مخکې»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_11.mp3', '', 1761754199, 1761754199),
(48134, 'Isaiah 62:12', 'Isaiah', 62, 12, 'هغوی یادیږي به په نوم «سپېڅلی قوم د څښتن» او «ژغورل شوي خلک د څښتن» ای اورشلیمه، ته به یاد شې «په څښتن باندې د ګران ښار» په نامه او د هغه ښار په نوم چې «نه دی پریښی څښتن»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah62_verse_12.mp3', '', 1761754199, 1761754199),
(48135, 'Ecclesiastes 12:1', 'Ecclesiastes', 12, 1, 'مخکې له دې چې درباندې سختې ورځې راشي او هغه کلونه راشي چې ته ووایې: «نور زما د ژوند خوند نشته» نو د ځوانۍ په ورځو کې خپل خالق په یاد لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_1.mp3', '', 1761754199, 1761754199),
(48136, 'Ecclesiastes 12:2', 'Ecclesiastes', 12, 2, 'مخکې له دې چې د لمر رڼا کمه شي او د سپوږمۍ او ستورو روښنایي لاړه شي او د باران د ورېدو نه وروسته تورې ورېځې بېرته په اسمان کې راښکاره شي نو خپل خالق په یاد لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_2.mp3', '', 1761754199, 1761754199),
(48137, 'Ecclesiastes 12:3', 'Ecclesiastes', 12, 3, 'مخکې له دې چې د کور ساتونکي په لړزېدو شي او د قوي سړیو ملاګانې کړوپې شي کله چې میچن کوونکې ښځې کمې او کار یې بند شي او د مېرمنو په سترګو چې له کړکیو لاندې ګوري، پرده راښکته شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_3.mp3', '', 1761754199, 1761754199),
(48138, 'Ecclesiastes 12:4', 'Ecclesiastes', 12, 4, 'او د کوڅو دروازې بندې شي کله چې د میچن کړسهار ټیټ او چوپ شي او د مرغیو په سهارنۍ نغمو باندې انسان له خوبه راویښ شي او بیا ټول غږونه هغه ته ټیټ او بند شي نو خپل خالق په یاد لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_4.mp3', '', 1761754199, 1761754199),
(48139, 'Ecclesiastes 12:5', 'Ecclesiastes', 12, 5, 'بله دا چې انسان ته له لوړ ځایه د لوېدو وېره پیدا شي یا په لارو کوڅو کې ورته د خطرونو اندېښنه پیدا شي او د بادام ونه غوټۍ ونیسي او ګلان په کې ښکاره شي یا ملخ په ځمکه ستومانه په څښېدلو شي یا په انسان کې د شهوت شوق ختم شي نو خپل خالق په یاد لره ځکه انسان ګور یعنې خپل تلپاتې کور ته ځي او ماتم کوونکي په کوڅه کې له هغه نه شاوخوا تاویږي راتاویږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_5.mp3', '', 1761754199, 1761754199),
(48140, 'Ecclesiastes 12:6', 'Ecclesiastes', 12, 6, 'مخکې له دې چې د سپینو زرو زنځیر وشلیږي یا د سرو زرو کاسه کړوپه شي یا د اوبو منګی د چینې تر‌څنګ مات شي یا د څاه څرخ ټوټې ټوټې شي نو خپل خالق په یاد لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_6.mp3', '', 1761754199, 1761754199),
(48141, 'Ecclesiastes 12:7', 'Ecclesiastes', 12, 7, 'مخکې له دې چې انسان بېرته خاورو ته لاړ شي له کومې څخه چې جوړ شوی ؤ او د ژوندون روح یې بېرته خدای ته لاړ شي چې هغه یې د هغه په پوزه کې پو کړی ؤ نو خپل خالق په یاد لره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_7.mp3', '', 1761754199, 1761754199),
(48142, 'Ecclesiastes 12:8', 'Ecclesiastes', 12, 8, 'دا څېړونکی وایي: «لوګی او پوکی! نو دا هرڅه لوګي او پوکي دي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_8.mp3', '', 1761754199, 1761754199),
(48143, 'Ecclesiastes 12:9', 'Ecclesiastes', 12, 9, 'نو بله خبره دا ده، چې دا څېړونکی ډېر پوه ؤ او په هرڅه چې پوهېده، نورو خلکو ته یې ورزده کړل. هغه ډېر متلونه وڅېړل، په هغو باندې یې غور او فکر وکړ او هغه یې راټول کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_9.mp3', '', 1761754199, 1761754199),
(48144, 'Ecclesiastes 12:10', 'Ecclesiastes', 12, 10, 'دې څېړونکي هڅه وکړه چې خواږه الفاظ پیدا کړي او په رښتیني توګه خپل د حقیقت خبرې پرې ولیکي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_10.mp3', '', 1761754199, 1761754199),
(48145, 'Ecclesiastes 12:11', 'Ecclesiastes', 12, 11, 'د هوښیارانو خبرې لکه د شپنو د لښتو په شان دردناکه دي او د ادیبانو د متلونو ټولګې د تېرو مېخونو په شان ګټورې دي نو دا شیان یو شپون خپلې رمې ته ورزده کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_11.mp3', '', 1761754199, 1761754199),
(48146, 'Ecclesiastes 12:12', 'Ecclesiastes', 12, 12, 'نو ای زما زویه! دې نورو خبرو ته مې هم پام وکړه. د کتابونو لیکل به هېڅکله ختم نه شي او په ډېرو لوستلو او زده کولو سره سړی ستړی ستومانه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_12.mp3', '', 1761754199, 1761754199),
(48147, 'Ecclesiastes 12:13', 'Ecclesiastes', 12, 13, 'خبرې ختمې شوې او هرڅه واورېدل شول. نو له خدای څخه وېره کوه او د هغه له حکمونو څخه اطاعت کوه، ځکه چې دا د هر انسان دنده ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_13.mp3', '', 1761754199, 1761754199),
(48148, 'Ecclesiastes 12:14', 'Ecclesiastes', 12, 14, 'نو خدای به د هر هغه کار په اړه قضاوت وکړي چې انسان یې تر‌سره کوي چې د زړه پټ رازونه هم په کې شامل دي، که هغه ښه وي او که بد.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ecclesiastes12_verse_14.mp3', '', 1761754199, 1761754199),
(48149, 'Job 1:1', 'Job', 1, 1, 'په يوه زمانه کښې د عُوض په مُلک کښې يو سړے وو چې نوم يې ايُوب وو. دا يو بې‌داغه او نېک سړے وو، هغه يو داسې کس وو چې د خُدائ پاک نه يرېدو او د بدۍ نه يې ځان ساتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_1.mp3', '', 1761754199, 1761754199),
(48150, 'Job 1:2', 'Job', 1, 2, 'د هغۀ اووۀ زامن او درې لوڼه وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_2.mp3', '', 1761754199, 1761754199),
(48151, 'Job 1:3', 'Job', 1, 3, 'هغۀ سره اووۀ زره ګډې، درې زره اوښان، د غوَيانو پينځۀ سوه قلبې، پينځۀ سوه خرې وې او ډېر زيات نوکران يې وُو، نو دے د مشرقى علاقې په خلقو کښې د ټولو نه زيات مالداره وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_3.mp3', '', 1761754199, 1761754199),
(48152, 'Job 1:4', 'Job', 1, 4, 'د هغۀ زامنو په خپلو کورونو کښې وار په وار مېلمستيا کوله، او هغوئ به خپلو درې واړو خوېندو له دعوت ورکولو چې د هغوئ سره خوراک څښاک وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_4.mp3', '', 1761754199, 1761754199),
(48153, 'Job 1:5', 'Job', 1, 5, 'او کله به چې د مېلمستيا ورځ تېره شوه، نو ايُوب به سحر وختى پاڅېدو او د هر يو بچى دپاره يې د ګناه نه د پاکوالى سوزېدونکې نذرانه پېش کوله، ايُوب به همېشه دا کار د دې دپاره کولو چې د هغۀ خيال وو چې کېدے شى چې زما بچو ګناه کړې وى او په خپلو زړُونو کښې يې خُدائ پاک ته بدرد وئيلى وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_5.mp3', '', 1761754199, 1761754199),
(48154, 'Job 1:6', 'Job', 1, 6, 'يو ځل آسمانى مخلوق راغلل چې خپل ځانونه د مالِک خُدائ په مخکښې حاضر کړى او شېطان هم د هغوئ سره راغلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_6.mp3', '', 1761754199, 1761754199),
(48155, 'Job 1:7', 'Job', 1, 7, 'مالِک خُدائ شېطان ته وفرمائيل، ”تا څۀ کول؟“ نو شېطان مالِک خُدائ ته ووئيل، ”زۀ په دُنيا کښې ګرځېدم راګرځېدم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_7.mp3', '', 1761754199, 1761754199),
(48156, 'Job 1:8', 'Job', 1, 8, 'نو مالِک خُدائ شېطان ته وفرمائيل، ”ستا زما د خِدمت کوونکى ايُوب په باره کښې څۀ خيال دے؟ ګوره په دُنيا کښې د هغۀ په شان هيڅ څوک هم نشته، هغه يو بې‌داغه او نېک سړے دے چې هغه د خُدائ پاک نه يريږى او د بدۍ نه ځان ساتى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_8.mp3', '', 1761754199, 1761754199),
(48157, 'Job 1:9', 'Job', 1, 9, 'بيا شېطان مالِک خُدائ ته ووئيل، ”آو، خو ايُوب په څۀ وجه د خُدائ پاک نه يريږى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_9.mp3', '', 1761754199, 1761754199),
(48158, 'Job 1:10', 'Job', 1, 10, 'تا همېشه د هغۀ، د هغۀ د کور او د هغۀ د هر څۀ حِفاظت کړے دے، تا هغۀ له په هر کار کښې برکت ورکړے دے او په دې مُلک کښې تا هغۀ له بې‌شمېره رَمې ورکړې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_10.mp3', '', 1761754199, 1761754199),
(48159, 'Job 1:11', 'Job', 1, 11, 'خو کۀ تۀ اوس د هغۀ نه هغه هر څۀ واخلې نو هغه به ستا په حضور کښې په تا لعنت ووائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_11.mp3', '', 1761754199, 1761754199),
(48160, 'Job 1:12', 'Job', 1, 12, 'نو مالِک خُدائ شېطان ته وفرمائيل، ”بلکل ټيک ده د هغۀ سره چې هر څۀ دى هغه ستا په اختيار کښې دى، خو چې هغه تباه نۀ کړې.“ نو شېطان د مالِک خُدائ د حضور نه لاړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_12.mp3', '', 1761754199, 1761754199),
(48161, 'Job 1:13', 'Job', 1, 13, 'يوه ورځ چې د هغۀ زامنو او لوڼو د خپل مشر ورور په کور کښې روټۍ خوړله او مے يې څښل،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_13.mp3', '', 1761754199, 1761754199),
(48162, 'Job 1:14', 'Job', 1, 14, 'نو يو پېغام وړونکے ايُوب له راغلو او ورته يې ووئيل، ”غوَيانو يوې کولې او خرې يې په څنګ کښې څرېدلې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_14.mp3', '', 1761754199, 1761754199),
(48163, 'Job 1:15', 'Job', 1, 15, 'او د سبائيانو څۀ خلقو حمله وکړه او څاروى يې بوتلل او نوکران يې په تُوره ووژل، يواځې زۀ ژوندے پاتې يم چې تا خبر کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_15.mp3', '', 1761754199, 1761754199),
(48164, 'Job 1:16', 'Job', 1, 16, 'هغۀ لا خبرې ختمې کړې نۀ وې چې يو بل کس راغلو او وې وئيل، ”د خُدائ پاک تندر د آسمان نه راوغورزېدو او ګډې او نوکران يې وسوزول او هلاک يې کړل، يواځې زۀ ژوندے يم چې تا خبر کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_16.mp3', '', 1761754199, 1761754199),
(48165, 'Job 1:17', 'Job', 1, 17, 'کله چې هغۀ لا خبرې کولې، نو يو بل کس راغلو او وې وئيل، ”کسديانو درې قبيلې جوړې کړې، او حمله يې وکړه او اوښان يې بوتلل او نوکران يې په تُوره باندې ووژل، يواځې زۀ ژوندے پاتې يم چې تا خبر کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_17.mp3', '', 1761754199, 1761754199),
(48166, 'Job 1:18', 'Job', 1, 18, 'کله چې هغۀ لا خبرې کولې، نو يو بل کس راغلو او وې وئيل، ”ستا زامنو او لوڼو د خپل مشر ورور په کور کښې خوراک څښاک کولو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_18.mp3', '', 1761754199, 1761754199),
(48167, 'Job 1:19', 'Job', 1, 19, 'چې ناڅاپه د صحرا د طرف نه يوه لويه هوا راغله او دې هوا د کور څلور واړه ګوټونه وخوځول او کور ستا په بچو باندې راوغورزېدو او هغوئ مړۀ شول، يواځې زۀ ژوندے پاتې يم چې تا خبر کړم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_19.mp3', '', 1761754199, 1761754199),
(48168, 'Job 1:20', 'Job', 1, 20, 'نو بيا ايُوب پاڅېدو، خپله چُوغه يې وشلوله، خپل سر يې کل کړو او په زمکه باندې يې سجده ولګوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_20.mp3', '', 1761754199, 1761754199),
(48169, 'Job 1:21', 'Job', 1, 21, 'هغۀ وفرمائيل، ”زۀ د مور نه خالى لاسونه پېدا وم او خالى لاسونه به د دې دُنيا نه ځم، هر څۀ ما له مالِک خُدائ راکړى وُو او مالِک خُدائ رانه واپس واخستل، د مالِک خُدائ د نوم ثناء صِفت دې وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_21.mp3', '', 1761754199, 1761754199),
(48170, 'Job 1:22', 'Job', 1, 22, 'د دې هر څۀ باوجود ايُوب په خُدائ پاک د اِلزام لګولو ګناه ونۀ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job1_verse_22.mp3', '', 1761754199, 1761754199),
(48171, 'Daniel 10:1', 'Daniel', 10, 1, 'د فارس د بادشاه خورس د بادشاهۍ په درېم کال ما دانيال ته چې راته بيلطشضر هم وئيل کېدو يوه رويا راکړے شوه. د دې پېغام حقيقت وو او دا د يو لوئ جنګ په حقله وه. د رويا په وسيله زۀ په دې پېغام پوهه شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_1.mp3', '', 1761754199, 1761754199),
(48172, 'Daniel 10:2', 'Daniel', 10, 2, 'کله چې دا رويا ما وليده نو په هغه وخت کښې ما دانيال د درې هفتو نه ماتم کولو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_2.mp3', '', 1761754199, 1761754199),
(48173, 'Daniel 10:3', 'Daniel', 10, 3, 'ما نۀ ښۀ خوراک کړے وو،نۀ مې غوښه او نۀ مې مے خپلو شونډو ته نزدې کړى وُو، او ما د درېو هفتو د تېرېدو پورې د سر تېل هم استعمال کړى نۀ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_3.mp3', '', 1761754199, 1761754199),
(48174, 'Daniel 10:4', 'Daniel', 10, 4, 'د وړومبۍ مياشتې په څليريشتمه ورځ، کله چې زۀ د دجله د لوئ سيند په غاړه ولاړ وم،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_4.mp3', '', 1761754199, 1761754199),
(48175, 'Daniel 10:5', 'Daniel', 10, 5, 'هر کله چې ما بره وکتل نو ځان ته مخامخ مې يو سړے وليدو چې د سپين کتان جامې يې اغوستې وې، او د ملا نه يې د سوچه سرو زرو ملابند تړلے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_5.mp3', '', 1761754199, 1761754199),
(48176, 'Daniel 10:6', 'Daniel', 10, 6, 'د هغۀ بدن د ايکوامرين کاڼى په شان وو، د هغۀ مخ لکه د برېښنا په شان ځلېدو، د هغۀ سترګې لکه د مشعلونو په شان بلېدلې، د هغۀ لاسونه او پښې لکه د زېړو په شان ځلېدل، او د هغۀ آواز لکه د لوئ ګڼې د شور په شان وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_6.mp3', '', 1761754199, 1761754199),
(48177, 'Daniel 10:7', 'Daniel', 10, 7, 'صرف ما دانيال، دا رويا وليده، ما سره نورو سړو دا ونۀ ليده، خو بيا هم هغوئ داسې وحشت واخستل چې وتښتېدل او ځانونه يې پټ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_7.mp3', '', 1761754199, 1761754199),
(48178, 'Daniel 10:8', 'Daniel', 10, 8, 'نو زۀ يواځې پاتې شوم چې دا عظيمه رويا وګورم. په ما کښې طاقت پاتې نۀ شو، زما رنګ د مړى په شان تک زېړ شو او بې‌دمه شوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_8.mp3', '', 1761754199, 1761754199),
(48179, 'Daniel 10:9', 'Daniel', 10, 9, 'نو بيا ما واورېدل چې هغۀ خبرې کولې، او څنګه چې ما هغۀ ته غوږ ونيولو، زۀ بې‌هوشه شوم، په زمکه پړمخې پرېوتلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_9.mp3', '', 1761754199, 1761754199),
(48180, 'Daniel 10:10', 'Daniel', 10, 10, 'بيا يو لاس زۀ راونيولم او په خپل ځائ يې په لړزېدو سره په ګوډو کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_10.mp3', '', 1761754199, 1761754199),
(48181, 'Daniel 10:11', 'Daniel', 10, 11, 'هغۀ وفرمائيل، ”اے دانياله، تۀ خُدائ پاک ته ډېر ګران يې، کومې خبرې چې زۀ تا ته کوم هغې ته غوږ ونيسه، او پاڅه ودرېږه، ځکه چې زۀ تا له رالېږلے شوے يم.“ او کله چې هغۀ ما ته دا وفرمائيل، نو زۀ په لړزېدو سره ودرېدلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_11.mp3', '', 1761754199, 1761754199),
(48182, 'Daniel 10:12', 'Daniel', 10, 12, 'بيا هغۀ خبره جارى وساتله، ”اے دانياله مۀ يرېږه. د وړومبۍ ورځې نه کله چې تا خپل سوچ دې ته تيار کړو چې پوهه حاصله کړې او د خُدائ پاک په وړاندې دې خپل ځان عاجز کړو، نو ستا دُعا قبوله شوه، او زۀ د هغې په جواب کښې راغلے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_12.mp3', '', 1761754199, 1761754199),
(48183, 'Daniel 10:13', 'Daniel', 10, 13, 'خو د فارس سلطنت روحانى شهزاده تر يوويشت ورځو پورې زما مخه ونيوله. بيا ميکائيل چې د فرښتو سردار دے، زما مدد کولو له راغلو ځکه چې زۀ د فارس بادشاه سره ګېر شوے وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_13.mp3', '', 1761754199, 1761754199),
(48184, 'Daniel 10:14', 'Daniel', 10, 14, 'زۀ اوس راغلے يم چې تاسو ته دا تشريح کړم چې په راتلونکى وخت کښې به ستا خلقو سره څۀ کيږى، ځکه چې د دې رويا تعلق د راتلونکى وخت سره دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_14.mp3', '', 1761754199, 1761754199),
(48185, 'Daniel 10:15', 'Daniel', 10, 15, 'کله چې هغۀ ما ته دا خبرې کولې نو ما لاندې زمکې ته کتل او ګونګا شوے وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_15.mp3', '', 1761754199, 1761754199),
(48186, 'Daniel 10:16', 'Daniel', 10, 16, 'نو بيا يو لکه د انسان په شان ښکارېدو هغۀ زما شونډې مسح کړې، او ما خپله خوله کولاو کړه او خبرې مې شروع کړې. ما هغه چا ته څوک چې زما په وړاندې ولاړ وو وئيل، ”مالِکه، زۀ د دې رويا په وجه اندېښنو راګېر کړے يم او په ما کښې زور ختم شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_16.mp3', '', 1761754199, 1761754199),
(48187, 'Daniel 10:17', 'Daniel', 10, 17, 'زۀ ستا نوکر څنګه تا سره خبرې وکړم، اے زما مالِکه؟ زما زور ختم شوے دے او ساه مې ځى راځى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_17.mp3', '', 1761754199, 1761754199),
(48188, 'Daniel 10:18', 'Daniel', 10, 18, 'نو هغه څوک چې د بنى آدم په شان ښکارېدو زۀ يې بيا مسح کړم او ما له يې طاقت راکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_18.mp3', '', 1761754199, 1761754199),
(48189, 'Daniel 10:19', 'Daniel', 10, 19, 'هغۀ وفرمائيل، ”اے خُدائ پاک ته، ګران انسانه مۀ يرېږه. سلامت اوسه. اوس ډاډه شه، ډاډه شه.“ کله چې هغۀ ما سره خبرې وکړې، ما ته طاقت مِلاو شو او ورته ومې ووئيل، ”اے مالِکه اوس خبره وکړه، ځکه چې تا ما له طاقت راکړے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_19.mp3', '', 1761754199, 1761754199),
(48190, 'Daniel 10:20', 'Daniel', 10, 20, 'نو بيا هغۀ وفرمائيل چې، ”تا ته پته ده چې زۀ ولې تا له راغلے يم؟ زۀ به زر د فارس د شهزاده خلاف جنګ له واپس لاړ شم، او څنګه چې زۀ لاړ شم، د يونان شهزاده به راشى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_20.mp3', '', 1761754199, 1761754199),
(48191, 'Daniel 10:21', 'Daniel', 10, 21, 'خو زۀ به اول تا ته هغه څۀ ووايم چې څۀ د حقيقت په کِتاب کښې ليکلے شوى دى. د دوئ خلاف هيڅ څوک هم زما مدد نۀ کوى بغېر د ميکائيل ستاسو د شهزاده نه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/daniel10_verse_21.mp3', '', 1761754199, 1761754199),
(48192, 'Isaiah 37:1', 'Isaiah', 37, 1, 'کله چې حزقیا پاچا دا خبره واورېدله، هغه له غمه خپل کالي وشکول، د ویر کالي یې واغوستل او د څښتن کور ته ورننوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_1.mp3', '', 1761754199, 1761754199),
(48193, 'Isaiah 37:2', 'Isaiah', 37, 2, 'هغه د ماڼۍ مسوول الیاقیم، د دربار منشي شبنا او د کاهنانو مشران چې ټولو د ویر کالي اغوستي وو، د آموص زوی اشعیا نبي ته ورولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_2.mp3', '', 1761754199, 1761754199),
(48194, 'Isaiah 37:3', 'Isaiah', 37, 3, 'دوی هغه ته وویل: «حزقیا پاچا داسې وایي: نن ورځ د خفګان ورځ ده، مونږ ته سزا راکول کیږي او سپکاوی راته شوی دی. مونږ د هغې ښځې په شان یو چې د اولاد زېږولو ته تیاره وي، خو د زېږولو قوت په کې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_3.mp3', '', 1761754199, 1761754199),
(48195, 'Isaiah 37:4', 'Isaiah', 37, 4, 'د اشور پاچا خپل لوړ رتبه مامور د دې دپاره رالېږلی دی چې د ژوندي خدای سپکاوی وکړي. ستا څښتن خدای دا د سپکاوۍ خبرې اورېدلې دي او هغه چا چې دا خبرې کړې دي، امکان لري چې هغه ته سزا ورکړي. نو د هغو کسانو دپاره دعا وکړئ چې ژوندي پاتې دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_4.mp3', '', 1761754199, 1761754199),
(48196, 'Isaiah 37:5', 'Isaiah', 37, 5, 'کله چې اشعیا د حزقیا پاچا پیغام تر لاسه کړ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_5.mp3', '', 1761754199, 1761754199),
(48197, 'Isaiah 37:6', 'Isaiah', 37, 6, 'هغه بېرته دا ځواب ورولېږه: «څښتن تاته داسې وایي چې اشوریان مه پرېږده چې په دې سپکو خبرو سره تا ووېروي چې څښتن تا نه شي ژغورلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_6.mp3', '', 1761754199, 1761754199),
(48198, 'Isaiah 37:7', 'Isaiah', 37, 7, 'څښتن به د اشور په پاچا ځینې ګونګوسې واوروي او هغه به مجبور کړي چې بېرته خپل هېواد ته ستون شي. هلته به یې په یو چا باندې ووژني.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_7.mp3', '', 1761754199, 1761754199),
(48199, 'Isaiah 37:8', 'Isaiah', 37, 8, 'کله چې د اشور لوړ رتبه مامور خبر شو چې پاچا د لاکیش څخه تللی دی او د لبنه د ښار په وړاندې جنګیږي، نو هلته ورغی چې د هغه سره مشوره وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_8.mp3', '', 1761754199, 1761754199),
(48200, 'Isaiah 37:9', 'Isaiah', 37, 9, 'اشوریانو ته خبر ورورسېد چې د مصر لښکر د ایتوپیا پاچا ترهاقه تر مشرۍ لاندې راروان دی چې حمله وکړي. کله چې د اشور پاچا دا خبره واورېدله، نو هغه د یهودا پاچا حزقیا ته د استازو په لاس لیک ورولېږه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_9.mp3', '', 1761754199, 1761754199),
(48201, 'Isaiah 37:10', 'Isaiah', 37, 10, '«په خپل خدای باور مه کوه او د هغه په هغې وعدې مه غولېږه چې زما په وړاندې به د اورشلیم څخه دفاع وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_10.mp3', '', 1761754199, 1761754199),
(48202, 'Isaiah 37:11', 'Isaiah', 37, 11, 'تا اورېدلي دي چې د اشور پاچاهانو د ټولو هېوادونو سره څه وکړل. هغه یې په پوره توګه له منځه یووړل. ایا فکر کوې چې ته به وژغورل شې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_11.mp3', '', 1761754199, 1761754199),
(48203, 'Isaiah 37:12', 'Isaiah', 37, 12, 'زما نیکونو د جوزان، حاران او رصف ښارونه له منځه یووړل او د عدن هغه خلک یې چې په تلسار کې اوسېدل، ووژل او د هغوی د خدایانو څخه هېڅ یو هغوی ونه ژغورل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_12.mp3', '', 1761754199, 1761754199),
(48204, 'Isaiah 37:13', 'Isaiah', 37, 13, 'د حمات، ارفاد، سفروایم، هینع او عوا د ښارونو پاچاهان چېرته دي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_13.mp3', '', 1761754199, 1761754199),
(48205, 'Isaiah 37:14', 'Isaiah', 37, 14, 'حزقیا پاچا د استازو څخه لیک واخیست او هغه یې ولوست. بیا هغه د څښتن کور ته لاړ، هغه لیک یې د څښتن په حضور کې پرانیست', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_14.mp3', '', 1761754199, 1761754199),
(48206, 'Isaiah 37:15', 'Isaiah', 37, 15, 'او داسې دعا یې وکړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_15.mp3', '', 1761754199, 1761754199),
(48207, 'Isaiah 37:16', 'Isaiah', 37, 16, '«ای مطلق قادر څښتنه، د اسراییلو خدایه چې د اسماني مخلوقاتو دپاسه په تخت ناست یې! تا اسمانونه او ځمکه پیدا کړي دي. ته یوازېنی خدای یې چې د نړۍ په ټولو پاچاهیو باندې پاچاهي کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_16.mp3', '', 1761754199, 1761754199),
(48208, 'Isaiah 37:17', 'Isaiah', 37, 17, 'نو ای څښتنه، وګوره چې په مونږ باندې څه تېریږي. ای ژوندی خدایه! د سنخاریب ټولې خبرې واوره، چې ستا سپکاوی کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_17.mp3', '', 1761754199, 1761754199),
(48209, 'Isaiah 37:18', 'Isaiah', 37, 18, 'ای څښتنه، دا رښتیا ده چې د اشور پاچاهانو ټول هېوادونه وران او له منځه وړي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_18.mp3', '', 1761754199, 1761754199),
(48210, 'Isaiah 37:19', 'Isaiah', 37, 19, 'او د هغوی خدایان یې سوځولي دي. هغه خدایان نه وو، هغه یوازې د لرګیو او تیږو هغه بتان وو چې د انسان په لاسونو جوړ شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah37_verse_19.mp3', '', 1761754199, 1761754199);